steps.body:
Breadth-first search (BFS) explores in rings: first every cell 1 step from the start, then every cell 2 steps away, and so on. A `std::queue` from `<queue>` keeps that order because cells leave in the order they arrived. So the first time BFS reaches a cell, it has found a shortest path to it, as long as every move costs the same.

```cpp harness
#include <bits/stdc++.h>

int main() {
    const int rows = 5;
    const int cols = 8;
    const int sr = 0;
    const int sc = 0;
    {{code}}
    std::cout << "dist[sr][sc] = " << dist[sr][sc] << '\n';
    return 0;
}
```

```cpp
std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));
std::queue<std::pair<int, int>> q;
dist[sr][sc] = 0;
q.push({sr, sc});
while (!q.empty()) {
    auto [r, c] = q.front();  // copy, then pop
    q.pop();
    // for each in-bounds, open neighbor (nr, nc) with dist -1:
    //     dist[nr][nc] = dist[r][c] + 1;
    //     q.push({nr, nc});
}
```

The `dist` grid does two jobs: -1 means not visited, anything else is the step count. Set it when you **push**, not when you pop, or one cell can enter the queue many times. Copy the front with `auto [r, c] = q.front();` before `pop()`: a `const auto&` would refer to an element that `pop()` destroys. The queue keeps its cells on the heap, so BFS handles grids far too big for recursive DFS and its 8 MB stack.

example.code:
#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>

const int DR[4] = {-1, 1, 0, 0};
const int DC[4] = {0, 0, -1, 1};

int main() {
    const std::vector<std::string> maze = {
        "S.#.....",
        ".##.##.#",
        "....#...",
        "##.##.#.",
        "......#E",
    };
    const int rows = static_cast<int>(maze.size());
    const int cols = static_cast<int>(maze[0].size());

    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));
    std::queue<std::pair<int, int>> q;
    int endR = 0;
    int endC = 0;
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (maze[r][c] == 'S') {
                dist[r][c] = 0;
                q.push({r, c});
            } else if (maze[r][c] == 'E') {
                endR = r;
                endC = c;
            }
        }
    }

    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d) {
            const int nr = r + DR[d];
            const int nc = c + DC[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            if (maze[nr][nc] == '#' || dist[nr][nc] != -1) {
                continue;
            }
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }
    std::cout << dist[endR][endC] << '\n';
    return 0;
}

