#include <algorithm>
#include <iostream>
#include <queue>
#include <utility>
#include <vector>

int fewestMoves(int start, int target) {
    const int limit = 2 * std::max(start, target);
    std::vector<bool> visited(limit + 1, false);
    std::queue<std::pair<int, int>> q;  // {value, moves so far}
    visited[start] = true;
    q.push({start, 0});
    while (!q.empty()) {
        auto [x, moves] = q.front();
        q.pop();
        if (x == target) {
            return moves;
        }
        const int nextValues[] = {x - 1, x * 2};
        for (int next : nextValues) {
            if (next >= 1 && next <= limit && !visited[next]) {
                visited[next] = true;
                q.push({next, moves + 1});
            }
        }
    }
    return -1;
}

int main() {
    int start = 0;
    int target = 0;
    std::cin >> start >> target;
    std::cout << fewestMoves(start, target) << '\n';
    return 0;
}
